//! The command offer, headless and offline: it appears only in the vault,
//! Settings and the install page take keys before the vault behind them,
//! and copying a command confirms in place.

#![cfg(test)]

use deadbolt_app::install::{Copied, Installer};
use deadbolt_app::model::{App, Screen};
use rune::{Env, Key, KeyEvent, Mods, Runtime};

const FRAME: f64 = 1.0 / 60.0;
const OFFER: &str = "Use Deadbolt from your terminal";

fn runtime(scene: &str) -> Runtime<App> {
    let app = rune::tooling::initial_state(&deadbolt_app::spec(), Some(scene));
    let mut rt = Runtime::new(
        app,
        deadbolt_app::view::app,
        (820.0, 540.0),
        Env {
            system_dark: true,
            scale: 1.0,
        },
    );
    rt.poll = Some(|s, now, tx| s.poll(now, tx));
    rt.on_key = Some(|s, ev, tx| s.on_key(ev, tx));
    rt
}

fn settle(rt: &mut Runtime<App>, seconds: f64) {
    for _ in 0..(seconds / FRAME).round() as usize {
        rt.frame(FRAME);
    }
}

fn shows(rt: &Runtime<App>, s: &str) -> bool {
    rt.elements()
        .iter()
        .any(|e| e.text.as_deref().is_some_and(|t| t.contains(s)) && e.opacity > 0.99)
}

fn press(rt: &mut Runtime<App>, key: &str) {
    let (x, y) = rt.find(key).unwrap_or_else(|| panic!("{key} is on screen"));
    rt.pointer_down(x, y);
    rt.pointer_up(x, y);
    settle(rt, 0.5);
}

fn key(key: Key) -> KeyEvent {
    KeyEvent {
        key,
        mods: Mods::default(),
    }
}

fn installer(rt: &Runtime<App>) -> &Installer {
    rt.state.installer.as_ref().unwrap()
}

/// Keys the vault's search field would act on: move, copy, type.
fn vault_keys(rt: &mut Runtime<App>) {
    for k in [Key::Down, Key::Up, Key::Enter, Key::Text("g".into())] {
        rt.key(key(k));
        rt.frame(FRAME);
    }
}

#[test]
fn the_offer_and_settings_live_in_the_vault_only() {
    for scene in [
        "connecting",
        "welcome",
        "create-typing",
        "ticket",
        "code",
        "creating",
        "locked",
        "failed",
    ] {
        let mut rt = runtime(scene);
        rt.update(|s, _| {
            let mut i = Installer::fixture();
            // Even an install page or Settings left open never covers these.
            i.open = true;
            s.installer = Some(i);
            s.settings_open = true;
        });
        settle(&mut rt, 0.6);
        assert!(!shows(&rt, OFFER), "{scene} shows the offer");
        assert!(!shows(&rt, "Install the deadbolt command"), "{scene}");
        assert!(
            rt.find("settings-trigger").is_none(),
            "{scene} has Settings"
        );
        assert!(
            !installer(&rt).open && !rt.state.settings_open,
            "{scene} closed them"
        );
    }
    let mut rt = runtime("command-offer");
    settle(&mut rt, 0.6);
    assert!(shows(&rt, OFFER));
    assert!(rt.find("settings-trigger").is_some());
}

#[test]
fn lock_and_settings_stay_in_the_narrowest_window() {
    let mut rt = runtime("command-offer");
    rt.set_viewport((640.0, 540.0), 1.0);
    settle(&mut rt, 0.5);
    let elements = rt.elements();
    // Off macOS the hint bar also opens the quick panel (macOS has its menus).
    let panel = (!cfg!(target_os = "macos")).then_some("Quick panel");
    for label in panel.into_iter().chain(["Lock", "Settings"]) {
        let e = elements
            .iter()
            .rfind(|e| e.text.as_deref() == Some(label) || e.label.as_deref() == Some(label))
            .unwrap_or_else(|| panic!("no {label:?}"));
        assert!(
            e.rect[0] + e.rect[2] <= 640.0,
            "{label:?} runs past the window: {:?}",
            e.rect
        );
    }
}

#[test]
fn the_offer_opens_the_page_or_goes_away_for_good() {
    let mut rt = runtime("command-offer");
    settle(&mut rt, 0.6);
    press(&mut rt, "open");
    assert!(rt.state.installing());
    assert!(shows(&rt, "Install the deadbolt command"));
    // Back to the vault; having seen the page answers the offer.
    press(&mut rt, "back");
    assert!(!rt.state.installing());
    assert!(!shows(&rt, OFFER));

    let mut rt = runtime("command-offer");
    settle(&mut rt, 0.6);
    press(&mut rt, "dismiss");
    assert!(installer(&rt).offered);
    assert!(!shows(&rt, OFFER));
}

#[test]
fn settings_takes_keys_before_the_focused_search() {
    let mut rt = runtime("command-offer");
    settle(&mut rt, 0.6);
    let selected = rt.state.selected.clone();
    // Open it without moving focus: the search field would get keys first.
    rt.update(|s, _| s.settings_open = true);
    settle(&mut rt, 0.5);
    assert!(shows(&rt, "Install deadbolt command…"));
    assert!(
        rt.state.search.focused,
        "search keeps focus under the popover"
    );

    vault_keys(&mut rt);
    assert_eq!(rt.state.selected, selected, "↑/↓ didn't move the selection");
    assert!(rt.state.copy.is_none(), "Enter didn't copy");
    assert_eq!(rt.state.search.text, "", "typing didn't search");

    rt.key(key(Key::Escape));
    settle(&mut rt, 0.3);
    assert!(!rt.state.settings_open, "Escape closed Settings");
    assert_eq!(rt.state.screen, Screen::Vault);

    // Closing hands focus back to the trigger. Back in the search field, the
    // same keys reach it again.
    rt.update(|s, _| s.search.focused = true);
    settle(&mut rt, 0.1);
    rt.key(key(Key::Down));
    rt.frame(FRAME);
    assert_ne!(rt.state.selected, selected);

    // Settings opens the install page, which also keeps keys from the vault.
    press(&mut rt, "settings-trigger");
    press(&mut rt, "install");
    assert!(rt.state.installing());
    let selected = rt.state.selected.clone();
    vault_keys(&mut rt);
    assert_eq!(rt.state.selected, selected);
    assert!(rt.state.copy.is_none());
    assert_eq!(rt.state.search.text, "");
    rt.key(key(Key::Escape));
    settle(&mut rt, 0.6);
    assert!(!rt.state.installing(), "Escape left the page");
    assert!(shows(&rt, "github.com"));
}

#[test]
fn the_page_is_centred_and_installs_in_place() {
    let mut rt = runtime("install-command");
    settle(&mut rt, 0.6);
    let (panel, _) = rt.presented("panel").unwrap();
    let middle = panel[1] + panel[3] / 2.0;
    // In the page under the 48 pt title bar, framed 8 pt from the bottom: (48 + 532) / 2.
    assert!((middle - 290.0).abs() < 2.0, "panel centred at {middle}");
    press(&mut rt, "action");
    assert!(installer(&rt).installed());
    assert!(shows(&rt, "Command installed"));
    assert!(shows(&rt, "To undo: rm"));
}

#[test]
fn copying_a_command_confirms_in_place() {
    let mut rt = runtime("install-command");
    rt.update(|s, _| {
        let i = s.installer.as_mut().unwrap();
        let scan = i.scan.as_mut().unwrap();
        scan.manual = true;
        scan.on_path = false;
    });
    settle(&mut rt, 0.6);
    assert!(shows(&rt, "sudo ln -s"));
    assert!(shows(&rt, "Copy command") && shows(&rt, "Copy PATH command"));
    rt.update(|s, tx| {
        let now = s.clock;
        s.installer.as_mut().unwrap().copy(Copied::Path, now, tx);
    });
    settle(&mut rt, 0.6);
    assert!(shows(&rt, "Copied"));
    assert!(shows(&rt, "Copy command"), "only the PATH command confirms");
    assert!(!shows(&rt, "Copy PATH command"));
    settle(&mut rt, 1.4);
    assert!(shows(&rt, "Copy PATH command"));
    assert!(!shows(&rt, "Copied"));
}

/// At the smallest window the manual path (two commands to copy) and an
/// error keep clear of the title bar band and Back.
#[test]
fn the_manual_path_stays_under_the_title_bar() {
    let mut rt = runtime("install-command");
    rt.update(|s, _| {
        let i = s.installer.as_mut().unwrap();
        i.error = Some("Couldn't link /Users/dax/.local/bin/deadbolt: permission denied.".into());
        let scan = i.scan.as_mut().unwrap();
        scan.manual = true;
        scan.on_path = false;
    });
    rt.set_viewport((640.0, 420.0), 1.0);
    settle(&mut rt, 0.6);
    let back = rt.presented("back").unwrap().0;
    let panel = rt.presented("panel").unwrap().0;
    assert!(
        panel[1] >= 48.0 && panel[1] >= back[1] + back[3],
        "the panel starts under the band: {panel:?}, Back {back:?}"
    );
    assert!(
        panel[1] + panel[3] <= 420.0,
        "and ends in the window: {panel:?}"
    );
}

//! The app against a real agent in a temporary home: first run (create, and
//! join between two agents), unlock, search, copy, lock. Drives Rune's
//! runtime headless (no window, no GPU) and an in-memory clipboard. Builds
//! the CLI from this repository for the agent.

#![cfg(test)]

mod support;

use std::time::{Duration, Instant};

use deadbolt_app::agent::{Agent, Job};
use deadbolt_app::model::{App, Screen};
use deadbolt_app::onboarding::worker::{ALREADY_SET_UP, NewDevice, Progress, Stage, Worker};
use deadbolt_app::onboarding::{Flow, Severity, Step};
use rune::{Env, Key, KeyEvent, Mods, Runtime};

use support::{Device, PASSPHRASE, key, shows, until};

#[test]
fn unlock_search_copy_lock() {
    let device = Device::new();
    device.run(&["init"]);
    device.run(&[
        "new",
        "login",
        "username=dax",
        "url=github.com",
        "password=hunter22",
    ]);
    device.run(&[
        "new",
        "login",
        "username=ops",
        "url=fly.io",
        "password=flyfly",
    ]);
    device.run(&["lock"]);

    let board = rune::clipboard::memory();
    let agent = Agent::spawn(device.paths(), device.launch());
    let mut rt = Runtime::new(
        App::new(agent),
        deadbolt_app::view::app,
        (820.0, 540.0),
        Env {
            system_dark: false,
            scale: 1.0,
        },
    );
    rt.use_clipboard(&board);
    rt.poll = Some(|s, now, tx| s.poll(now, tx));
    rt.on_key = Some(|s, ev, tx| s.on_key(ev, tx));
    rt.state.agent.send(deadbolt_app::agent::Job::Connect);

    until(&mut rt, "the locked screen", |s| s.screen == Screen::Locked);
    assert!(shows(&rt, "Deadbolt"));

    // A wrong passphrase stays on the unlock screen and says so.
    for c in "nope".chars() {
        rt.key(key(Key::Text(c.into())));
    }
    rt.frame(1.0 / 60.0);
    assert!(rt.has_secure_focus(), "a secure field takes it");
    assert!(
        !rt.elements()
            .iter()
            .any(|e| e.text.as_deref().is_some_and(|t| t.contains("nope")))
    );
    rt.key(key(Key::Enter));
    until(&mut rt, "the unlock error", |s| s.unlock_error.is_some());
    assert_eq!(rt.state.screen, Screen::Locked);

    // Typing clears the error; the agent stopping meanwhile is no obstacle.
    device.run(&["agent", "stop"]);
    rt.key(key(Key::Text(PASSPHRASE[..1].into())));
    rt.frame(1.0 / 60.0);
    assert_eq!(rt.state.unlock_error, None);
    rt.key(key(Key::Backspace));
    for c in PASSPHRASE.chars() {
        rt.key(key(Key::Text(c.into())));
    }
    rt.key(key(Key::Enter));
    until(&mut rt, "the vault", |s| {
        s.screen == Screen::Vault && s.loaded && s.detail.is_some()
    });
    assert!(shows(&rt, "github.com") && shows(&rt, "fly.io"));

    // Typing filters; the first match is selected and its fields load.
    for c in "fly".chars() {
        rt.key(key(Key::Text(c.into())));
    }
    until(&mut rt, "fly.io's fields", |s| {
        s.detail.as_ref().is_some_and(|d| d.label == "fly.io")
    });
    let visible: Vec<&str> = rt
        .state
        .visible()
        .iter()
        .map(|i| i.label.as_str())
        .collect();
    assert_eq!(visible, ["fly.io"]);

    // Enter copies the password and starts the countdown.
    rt.key(key(Key::Enter));
    rt.frame(1.0 / 60.0);
    assert_eq!(text(&board).as_deref(), Some("flyfly"));
    assert!(shows(&rt, "Copied, clears in 0:30"));

    // Shift+Enter copies the username in its place.
    rt.key(KeyEvent {
        key: Key::Enter,
        mods: Mods {
            shift: true,
            ..Mods::default()
        },
    });
    rt.frame(1.0 / 60.0);
    assert_eq!(text(&board).as_deref(), Some("ops"));

    // Escape, in the focused search field, clears the search; ↓ then moves
    // the selection to the next item.
    rt.key(key(Key::Escape));
    rt.frame(1.0 / 60.0);
    assert_eq!(rt.state.search.text, "");
    assert_eq!(rt.state.visible().len(), 2);
    let first = rt.state.selected.clone();
    rt.key(key(Key::Down));
    rt.frame(1.0 / 60.0);
    assert_ne!(rt.state.selected, first, "↓ moves the selection");

    // Locking clears our copy off the clipboard and forgets the vault.
    rt.key(KeyEvent {
        key: Key::Command('l'),
        mods: Mods {
            cmd: true,
            ..Mods::default()
        },
    });
    until(&mut rt, "the lock", |s| s.screen == Screen::Locked);
    assert_eq!(text(&board), None);
    assert!(rt.state.items.is_empty() && rt.state.detail.is_none());
}

/// The quick panel on its own agent connection: summoned locked, it unlocks
/// in place, filters, copies with ⏎ and closes itself.
#[test]
fn quick_panel_unlock_filter_copy() {
    use deadbolt_app::panel::Phase;
    let device = Device::new();
    device.run(&["init"]);
    device.run(&[
        "new",
        "login",
        "username=dax",
        "url=github.com",
        "password=hunter22",
    ]);
    device.run(&[
        "new",
        "login",
        "username=ops",
        "url=fly.io",
        "password=flyfly",
    ]);
    device.run(&["lock"]);

    let board = rune::clipboard::memory();
    let agent = Agent::spawn(device.paths(), device.launch());
    let mut rt = Runtime::new(
        App::panel(agent),
        deadbolt_app::panel::view::panel,
        deadbolt_app::panel::SIZE,
        Env {
            system_dark: true,
            scale: 1.0,
        },
    );
    rt.use_clipboard(&board);
    rt.poll = Some(|s, now, tx| s.poll(now, tx));
    rt.on_key = Some(|s, ev, tx| s.panel_key(ev, tx));
    rt.update(|s, tx| s.summon(tx));

    until(&mut rt, "the locked panel", |s| s.screen == Screen::Locked);
    assert!(shows(&rt, "Unlock Deadbolt"));
    type_text(&mut rt, PASSPHRASE);
    rt.key(key(Key::Enter));
    until(&mut rt, "the vault in the panel", |s| {
        s.screen == Screen::Vault && s.loaded && s.detail.is_some()
    });
    assert!(rt.state.search.focused, "the search takes the keys");

    type_text(&mut rt, "fly");
    until(&mut rt, "fly.io's fields", |s| {
        s.detail.as_ref().is_some_and(|d| d.label == "fly.io")
    });
    let visible: Vec<&str> = rt
        .state
        .visible()
        .iter()
        .map(|i| i.label.as_str())
        .collect();
    assert_eq!(visible, ["fly.io"]);
    assert!(shows(&rt, "fly.io"));

    rt.key(key(Key::Enter));
    rt.frame(1.0 / 60.0);
    assert_eq!(text(&board).as_deref(), Some("flyfly"));
    assert!(matches!(rt.state.panel_phase(), Some(Phase::Copied { .. })));
    until(&mut rt, "the panel to close", |s| {
        s.panel_phase() == Some(Phase::Hidden)
    });
    assert_eq!(
        text(&board).as_deref(),
        Some("flyfly"),
        "closing keeps the copy until it clears"
    );

    // Opened again: an empty search over both items, ready for ⇧⏎.
    rt.update(|s, tx| s.summon(tx));
    until(&mut rt, "the first item's fields", |s| s.detail.is_some());
    assert_eq!(rt.state.search.text, "");
    assert_eq!(rt.state.visible().len(), 2);
    rt.key(KeyEvent {
        key: Key::Enter,
        mods: Mods {
            shift: true,
            ..Mods::default()
        },
    });
    rt.frame(1.0 / 60.0);
    assert_eq!(text(&board).as_deref(), Some("ops"));
}

#[test]
fn the_clipboard_clears_itself_unless_something_else_was_copied() {
    let board = rune::clipboard::memory();
    let mut rt = Runtime::new(
        App::new(Agent::offline()),
        deadbolt_app::view::app,
        (820.0, 540.0),
        Env {
            system_dark: false,
            scale: 1.0,
        },
    );
    rt.use_clipboard(&board);
    rt.poll = Some(|s, now, tx| s.poll(now, tx));
    rt.state.clear_after = 1.0;
    // The "copied" scene's state, by hand: a vault with one item's fields.
    rt.state.screen = Screen::Vault;
    rt.state.detail = Some(deadbolt_client::protocol::ItemInfo {
        id: "a".into(),
        short: "a".into(),
        kind: "login".into(),
        label: "x".into(),
        detail: None,
        fields: vec![deadbolt_client::protocol::FieldInfo {
            name: "password".into(),
            kind: "secret".into(),
            value: "pw".into(),
        }],
        source: None,
    });
    rt.frame(0.0);
    rt.update(|s, tx| s.copy_field("password", tx));
    rt.frame(1.0 / 60.0);
    assert_eq!(text(&board).as_deref(), Some("pw"));
    for _ in 0..25 {
        rt.frame(0.05);
    }
    assert_eq!(text(&board), None, "cleared after a second");

    rt.update(|s, tx| s.copy_field("password", tx));
    rt.frame(1.0 / 60.0);
    board.set_text("mine");
    for _ in 0..25 {
        rt.frame(0.05);
    }
    assert_eq!(
        text(&board).as_deref(),
        Some("mine"),
        "a later copy of the user's own survives"
    );
}

/// The app for `device`, as `run` builds it, before it connects.
fn app(device: &Device) -> Runtime<App> {
    let mut app = App::new(Agent::spawn(device.paths(), device.launch()));
    app.onboarding.worker = Worker::new(device.paths(), device.launch());
    let mut rt = Runtime::new(
        app,
        deadbolt_app::view::app,
        (820.0, 540.0),
        Env {
            system_dark: true,
            scale: 1.0,
        },
    );
    rt.poll = Some(|s, now, tx| s.poll(now, tx));
    rt.on_key = Some(|s, ev, tx| s.on_key(ev, tx));
    rt.state.agent.send(Job::Connect);
    rt
}

fn text(board: &rune::clipboard::MemoryClipboard) -> Option<String> {
    board.text().map(|t| t.as_str().to_owned())
}

fn type_text(rt: &mut Runtime<App>, text: &str) {
    for c in text.chars() {
        rt.key(key(Key::Text(c.into())));
    }
    rt.frame(1.0 / 60.0);
}

/// Picks `flow` on the welcome screen and fills the form for a new device.
fn fill_form(rt: &mut Runtime<App>, flow: Flow, name: &str) {
    until(rt, "the welcome screen", |s| s.screen == Screen::Onboarding);
    assert!(shows(rt, "Deadbolt"));
    rt.update(|s, _| s.choose(flow));
    rt.update(|s, _| s.onboarding.device = rune::TextEdit::new(name));
    rt.frame(1.0 / 60.0);
    type_text(rt, PASSPHRASE);
    rt.key(key(Key::Enter));
    rt.frame(1.0 / 60.0);
    type_text(rt, PASSPHRASE);
    assert!(
        !rt.elements()
            .iter()
            .any(|e| e.text.as_deref().is_some_and(|t| t.contains(PASSPHRASE))),
        "the passphrase never shows"
    );
    rt.key(key(Key::Enter));
}

#[test]
fn create_a_vault_in_the_app() {
    let device = Device::new();
    let mut rt = app(&device);
    fill_form(&mut rt, Flow::Create, "alpha");
    until(&mut rt, "creating", |s| {
        matches!(s.onboarding.step, Step::Working(_) | Step::Done { .. })
    });
    until(&mut rt, "the moment", |s| {
        matches!(s.onboarding.step, Step::Done { .. })
    });
    assert!(shows(&rt, "Vault created"));
    until(&mut rt, "the empty vault", |s| {
        s.screen == Screen::Vault && s.loaded
    });
    assert!(rt.state.items.is_empty());
    assert!(rt.state.onboarding.passphrase.text.is_empty(), "wiped");
    until(&mut rt, "the vault's name", |s| {
        s.status.as_ref().is_some_and(|st| !st.vaults.is_empty())
    });
    assert!(shows(&rt, "personal is empty"));
    // The CLI sees the device and vault the app made.
    assert!(device.output(&["vault", "ls"]).contains("personal"));
    assert!(device.output(&["status"]).contains("alpha"));
}

/// Shows a ticket on `device`'s app and pairs it from `inviter`; returns the
/// inviter's `deadbolt pair` once the code is up.
fn pair_to_code(rt: &mut Runtime<App>, inviter: &Device, form: bool) -> std::process::Child {
    if form {
        fill_form(rt, Flow::Join, "beta");
    } else {
        rt.update(|s, _| s.submit_join());
    }
    until(rt, "the ticket", |s| s.onboarding.ticket.is_some());
    assert!(shows(rt, "Pair from your other device"));
    let ticket = rt.state.onboarding.ticket.as_ref().unwrap().text.clone();
    let pair = inviter.spawn(&["pair", &ticket, "--yes"]);
    until(rt, "the code", |s| {
        matches!(s.onboarding.step, Step::Confirm { .. })
    });
    let Step::Confirm { code, vault, .. } = &rt.state.onboarding.step else {
        unreachable!()
    };
    assert!(code.len() == 6 && code.chars().all(|c| c.is_ascii_digit()));
    assert_eq!(vault, "personal");
    pair
}

#[test]
fn join_from_another_device_in_the_app() {
    let inviter = Device::new();
    inviter.run(&["init"]);
    inviter.run(&[
        "new",
        "login",
        "username=dax",
        "url=github.com",
        "password=hunter22",
    ]);
    let device = Device::new();
    let mut rt = app(&device);
    let mut pair = pair_to_code(&mut rt, &inviter, true);
    rt.update(|s, _| s.answer_code(true));
    until(&mut rt, "joined", |s| {
        matches!(s.onboarding.step, Step::Done { .. })
    });
    assert!(shows(&rt, "Joined personal"));
    until(&mut rt, "the synced vault", |s| {
        s.screen == Screen::Vault && s.items.len() == 1
    });
    assert_eq!(rt.state.items[0].label, "github.com");
    assert!(
        pair.wait().unwrap().success(),
        "the inviter added this device"
    );
}

#[test]
fn declining_or_cancelling_a_join_keeps_the_device_set_up() {
    let inviter = Device::new();
    inviter.run(&["init"]);
    let device = Device::new();
    let mut rt = app(&device);

    // The codes "don't match": nothing is shared and both sides stop.
    let mut pair = pair_to_code(&mut rt, &inviter, true);
    rt.update(|s, _| s.answer_code(false));
    until(&mut rt, "the caution notice", |s| {
        s.onboarding.step == Step::Join && s.onboarding.notice.is_some()
    });
    let notice = rt.state.onboarding.notice.clone().unwrap();
    assert_eq!(notice.severity, Severity::Caution, "{notice:?}");
    assert!(!pair.wait().unwrap().success(), "the inviter stopped too");
    until(&mut rt, "the device set up", |s| s.onboarding.device_ready);

    // A second try needs no passphrase; cancelling it hangs up.
    rt.update(|s, _| s.submit_join());
    until(&mut rt, "the ticket", |s| s.onboarding.ticket.is_some());
    rt.key(key(Key::Escape));
    until(&mut rt, "the neutral notice", |s| {
        s.onboarding.step == Step::Join
            && s.onboarding
                .notice
                .as_ref()
                .is_some_and(|n| n.severity == Severity::Neutral)
    });
    assert!(shows(&rt, "Join cancelled"));
    assert!(rt.state.onboarding.ticket.is_none());
    assert!(device.output(&["vault", "ls"]).trim().is_empty());
}

#[test]
fn cancelling_a_join_during_setup_waits_for_it() {
    let device = Device::new().with_slow_kdf();
    let mut rt = app(&device);
    fill_form(&mut rt, Flow::Join, "beta");
    until(&mut rt, "the slow setup", |s| {
        s.onboarding.stage == Some(Stage::Protecting)
    });
    rt.key(key(Key::Escape));
    rt.frame(1.0 / 60.0);
    assert_eq!(
        rt.state.onboarding.step,
        Step::Working(Flow::Join),
        "it waits for the setup the agent is running"
    );
    until(&mut rt, "the neutral notice", |s| {
        s.onboarding.step == Step::Join && s.onboarding.notice.is_some()
    });
    let o = &rt.state.onboarding;
    // The form matches the agent: set up, so no passphrase to type again
    // (one typed now would never be used).
    assert!(o.device_ready, "the form still asks for a passphrase");
    let notice = o.notice.clone().unwrap();
    assert_eq!(notice.severity, Severity::Neutral, "{notice:?}");
    assert!(notice.body.contains("set up now"), "{notice:?}");
    assert!(o.ticket.is_none(), "no ticket after the cancel");
    assert!(device.output(&["status"]).contains("beta"));
}

/// Runs `worker` until it reports the end of its request, collecting what it said.
fn finish(worker: &mut Worker) -> Vec<Progress> {
    let start = Instant::now();
    let mut seen = Vec::new();
    loop {
        let (progress, _) = worker.drain(0.0);
        for p in progress {
            let end = matches!(p, Progress::Created(_) | Progress::Joined(_));
            seen.push(p);
            if end {
                return seen;
            }
        }
        assert!(
            start.elapsed() < Duration::from_secs(20),
            "timed out: {seen:?}"
        );
        std::thread::sleep(Duration::from_millis(10));
    }
}

#[test]
fn a_device_set_up_meanwhile_refuses_the_new_passphrase() {
    let device = Device::new();
    // Set up behind the screen's back, after it showed the form.
    device.run(&["init"]);
    let new_device = || {
        Some(NewDevice {
            name: "beta".into(),
            passphrase: zeroize::Zeroizing::new("another passphrase".into()),
        })
    };
    let mut worker = Worker::new(device.paths(), device.launch());
    worker.create(new_device(), "work".into());
    let seen = finish(&mut worker);
    assert!(
        matches!(seen.last(), Some(Progress::Created(Err(f))) if f.message == ALREADY_SET_UP),
        "{seen:?}"
    );
    worker.join(new_device());
    let seen = finish(&mut worker);
    assert!(
        matches!(seen.last(), Some(Progress::Joined(Err(f))) if f.message == ALREADY_SET_UP),
        "{seen:?}"
    );
    assert!(!seen.iter().any(|p| matches!(p, Progress::Ticket(_))));
    assert!(!device.output(&["vault", "ls"]).contains("work"));
    // The passphrase it was set up with still unlocks it.
    device.run(&["lock"]);
    device.run(&["unlock"]);
}

/// The app follows the agent with no input of its own: items written
/// elsewhere appear, locks and unlocks from the CLI carry over, and a
/// restarted agent is found again.
#[test]
fn the_app_follows_the_agent() {
    let device = Device::new();
    device.run(&["init"]);
    device.run(&[
        "new",
        "login",
        "username=dax",
        "url=github.com",
        "password=hunter22",
    ]);
    let mut rt = app(&device);
    until(&mut rt, "the vault", |s| {
        s.screen == Screen::Vault && s.loaded && s.detail.is_some()
    });
    let selected = rt.state.selected.clone();

    device.run(&[
        "new",
        "login",
        "username=ops",
        "url=fly.io",
        "password=flyfly",
    ]);
    until(&mut rt, "the new item", |s| s.items.len() == 2);
    assert!(shows(&rt, "fly.io"));
    assert_eq!(rt.state.selected, selected, "the selection stays");
    assert!(rt.state.detail.is_some(), "the selected item stays shown");

    device.run(&["lock"]);
    until(&mut rt, "the lock", |s| s.screen == Screen::Locked);
    assert!(rt.state.items.is_empty() && rt.state.detail.is_none());

    device.run(&["unlock"]);
    until(&mut rt, "the vault again", |s| {
        s.screen == Screen::Vault && s.items.len() == 2
    });

    device.run(&["agent", "stop"]);
    until(&mut rt, "the lock when the agent stops", |s| {
        s.screen == Screen::Locked
    });

    // A new agent, unlocked from the CLI: the app finds it on its own.
    device.run(&["unlock"]);
    until(&mut rt, "the vault from the new agent", |s| {
        s.screen == Screen::Vault && s.items.len() == 2
    });
}

/// The selected item deleted from the CLI: the next one replaces it in the
/// frame the list lands, and nothing of the old item, its revealed password
/// least of all, fades out under the new title.
#[test]
fn a_deleted_selection_goes_at_once() {
    let device = Device::new();
    device.run(&["init"]);
    for (url, user, password) in [
        ("github.com", "dax", "hunter22"),
        ("fly.io", "ops", "flyfly"),
    ] {
        let (url, user, password) = (
            format!("url={url}"),
            format!("username={user}"),
            format!("password={password}"),
        );
        device.run(&["new", "login", &user, &url, &password]);
    }
    let mut rt = app(&device);
    until(&mut rt, "the vault", |s| {
        s.screen == Screen::Vault && s.items.len() == 2 && s.detail.is_some()
    });
    assert_eq!(rt.state.selected_item().unwrap().label, "fly.io");
    rt.update(|s, _| s.revealed.push("password".into()));
    for _ in 0..30 {
        rt.frame(1.0 / 60.0);
    }
    // Shown through Rune's secure path, so never as text.
    assert!(
        rt.elements()
            .iter()
            .any(|e| e.path.ends_with("field-password/value") && e.role == "textbox"),
        "the password shows"
    );
    assert!(!shows(&rt, "flyfly"));

    device.run(&["rm", "fly.io"]);
    let start = Instant::now();
    while rt.state.items.len() == 2 {
        assert!(
            start.elapsed() < Duration::from_secs(20),
            "the delete lands"
        );
        rt.frame(1.0 / 60.0);
        std::thread::sleep(Duration::from_millis(5));
    }
    assert_eq!(rt.state.selected_item().unwrap().label, "github.com");
    let elements = rt.elements();
    let old: Vec<_> = elements
        .iter()
        .filter(|e| {
            let field = e.key.as_deref().is_some_and(|k| k.starts_with("field-"));
            let text = e.text.as_deref();
            (field && e.opacity < 1.0) || matches!(text, Some("flyfly" | "ops" | "fly.io"))
        })
        .map(|e| (e.key.clone(), e.text.clone(), e.opacity))
        .collect();
    assert!(old.is_empty(), "the old item lingers: {old:?}");
}

/// The open form's field `name`.
fn form_value(s: &App, name: &str) -> String {
    let form = s.edit.form.as_ref().expect("a form");
    let input = form.fields.iter().find(|f| f.name == name).unwrap();
    input.edit.text.to_string()
}

fn fill(rt: &mut Runtime<App>, name: &str, value: &str) {
    rt.update(|s, _| {
        let form = s.edit.form.as_mut().expect("a form");
        let input = form.fields.iter_mut().find(|f| f.name == name).unwrap();
        input.edit.replace_text(value);
        s.form_changed();
    });
    rt.frame(1.0 / 60.0);
}

fn command(c: char) -> KeyEvent {
    KeyEvent {
        key: Key::Command(c),
        mods: Mods {
            cmd: true,
            ..Mods::default()
        },
    }
}

/// Adding, changing and deleting against a real agent: ⌘N with the agent's
/// generated password, an edit that changes one field and empties another,
/// and a delete, each as the CLI then sees it.
#[test]
fn add_edit_and_delete_items() {
    let device = Device::new();
    device.run(&["init"]);
    device.run(&[
        "new",
        "login",
        "username=dax",
        "url=github.com",
        "password=hunter22",
    ]);
    let agent = Agent::spawn(device.paths(), device.launch());
    let mut rt = Runtime::new(
        App::new(agent),
        deadbolt_app::view::app,
        (820.0, 540.0),
        Env {
            system_dark: false,
            scale: 1.0,
        },
    );
    rt.poll = Some(|s, now, tx| s.poll(now, tx));
    rt.on_key = Some(|s, ev, tx| s.on_key(ev, tx));
    rt.state.agent.send(Job::Connect);
    until(&mut rt, "the vault", |s| {
        s.screen == Screen::Vault && s.loaded && s.detail.is_some()
    });

    // ⌘N: a new login, its password from the agent's generator.
    rt.key(command('n'));
    until(&mut rt, "a generated password", |s| {
        s.editing() && !form_value(s, "password").is_empty()
    });
    let password = [REDACTED], "password");
    assert_eq!(password.chars().count(), 24);
    for c in "Linear".chars() {
        rt.key(key(Key::Text(c.into())));
    }
    fill(&mut rt, "username", "kit");
    rt.key(command('s'));
    until(&mut rt, "the new login, selected", |s| {
        !s.editing()
            && s.selected_item().is_some_and(|i| i.label == "Linear")
            && s.detail.as_ref().is_some_and(|d| d.label == "Linear")
    });
    assert_eq!(rt.state.items.len(), 2);
    assert_eq!(device.output(&["get", "Linear"]).trim(), password);
    assert_eq!(
        device.output(&["get", "-f", "username", "Linear"]).trim(),
        "kit"
    );

    // ⌘E: a new URL, the username emptied, saved as one change.
    rt.key(command('e'));
    rt.frame(1.0 / 60.0);
    assert_eq!(form_value(&rt.state, "username"), "kit");
    fill(&mut rt, "username", "");
    fill(&mut rt, "url", "linear.app");
    rt.key(command('s'));
    until(&mut rt, "the edit, saved", |s| {
        !s.editing()
            && s.detail.as_ref().is_some_and(|d| {
                d.fields.iter().any(|f| f.value == "https://linear.app")
                    && !d.fields.iter().any(|f| f.name == "username")
            })
    });
    assert_eq!(
        device.output(&["get", "-f", "url", "Linear"]).trim(),
        "https://linear.app"
    );
    assert_eq!(device.output(&["get", "Linear"]).trim(), password);

    // ⌘⌫ asks; ⏎ deletes, and github.com takes its place.
    rt.key(KeyEvent {
        key: Key::Backspace,
        mods: Mods {
            cmd: true,
            ..Mods::default()
        },
    });
    rt.frame(1.0 / 60.0);
    assert!(shows(&rt, "Delete “Linear”?"));
    rt.key(key(Key::Enter));
    until(&mut rt, "the delete", |s| {
        s.items.len() == 1 && s.detail.as_ref().is_some_and(|d| d.label == "github.com")
    });
    assert!(!device.output(&["ls"]).contains("Linear"));
}

//! `watch` through the agent: what a watcher sees, that a stuck watcher
//! can't hold the agent up, and locking on system events.

use std::sync::Arc;
use std::time::Duration;

use deadbolt_core::{DeviceSecret, Field, FieldType, VaultId};
use deadbolt_net::SyncHandler;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader, Lines};
use tokio::net::UnixStream;
use tokio::net::unix::OwnedReadHalf;
use tokio::sync::mpsc;
use tokio::task::JoinSet;
use zeroize::Zeroizing;

use super::session::Changes;
use super::system::SystemEvent;
use super::tests::test_paths;
use super::{Agent, MAX_LINE, items, sync, watchers};
use crate::protocol::{Change, Command, FieldInput, Message, PROTOCOL_VERSION, Reply, Request};

const KDF: deadbolt_store::KdfParams = deadbolt_store::KdfParams {
    m_cost_kib: 64,
    t_cost: 1,
    p_cost: 1,
};
/// Long enough for any real change to arrive; quiet after that means none came.
const QUIET: Duration = Duration::from_millis(300);
const STEP: Duration = Duration::from_secs(10);

fn agent(dir: &std::path::Path) -> Arc<Agent> {
    Agent::new(test_paths(dir), true, KDF)
}

fn passphrase() -> Zeroizing<String> {
    Zeroizing::new("test".into())
}

fn request(command: Command) -> Vec<u8> {
    let mut line = serde_json::to_vec(&Request {
        v: PROTOCOL_VERSION,
        command,
    })
    .unwrap();
    line.push(b'\n');
    line
}

/// Subscribes over a socket pair, returning the watcher's lines.
async fn subscribe(
    agent: &Arc<Agent>,
    connections: &mut JoinSet<anyhow::Result<()>>,
) -> (
    Lines<BufReader<OwnedReadHalf>>,
    tokio::net::unix::OwnedWriteHalf,
) {
    let (server, client) = UnixStream::pair().unwrap();
    connections.spawn(agent.clone().handle(server, MAX_LINE));
    let (read, mut write) = client.into_split();
    write.write_all(&request(Command::Watch)).await.unwrap();
    let mut lines = BufReader::new(read).lines();
    assert_eq!(next(&mut lines).await, Some(Change::Watching));
    (lines, write)
}

/// The next change, or `None` for the final reply.
async fn next(lines: &mut Lines<BufReader<OwnedReadHalf>>) -> Option<Change> {
    let line = tokio::time::timeout(STEP, lines.next_line())
        .await
        .expect("a change in time")
        .unwrap()
        .expect("the stream is open");
    match serde_json::from_str::<Message>(&line).unwrap() {
        Message::Change { change } => Some(change),
        Message::Ok { reply: Reply::Done } => None,
        other => panic!("unexpected {other:?}"),
    }
}

async fn changes(lines: &mut Lines<BufReader<OwnedReadHalf>>, n: usize) -> Vec<Change> {
    let mut out = Vec::new();
    for _ in 0..n {
        out.push(next(lines).await.expect("a change"));
    }
    out
}

async fn quiet(lines: &mut Lines<BufReader<OwnedReadHalf>>) {
    if let Ok(line) = tokio::time::timeout(QUIET, lines.next_line()).await {
        panic!("expected no change, got {line:?}");
    }
}

fn items_in(vault: VaultId) -> Change {
    Change::Items {
        vault: vault.to_string(),
    }
}

fn devices_in(vault: VaultId) -> Change {
    Change::Devices {
        vault: vault.to_string(),
    }
}

#[tokio::test]
async fn a_watcher_sees_lock_state_local_writes_and_one_change_per_sync_batch() {
    let dir = tempfile::tempdir().unwrap();
    let agent = agent(dir.path());
    let mut connections = JoinSet::new();
    let (mut lines, _write) = subscribe(&agent, &mut connections).await;

    agent.setup(passphrase(), "device".into()).await.unwrap();
    assert_eq!(next(&mut lines).await, Some(Change::Unlocked));
    agent.lock().await;
    assert_eq!(next(&mut lines).await, Some(Change::Locked));
    agent.unlock(passphrase(), None).await.unwrap();
    assert_eq!(next(&mut lines).await, Some(Change::Unlocked));
    quiet(&mut lines).await;

    let vault = agent.with(|s| s.create_vault("personal")).unwrap();
    assert_eq!(
        changes(&mut lines, 3).await,
        [Change::Vaults, devices_in(vault), items_in(vault)]
    );
    let fields = vec![FieldInput {
        name: "password".into(),
        kind: None,
        value: "local".into(),
    }];
    agent
        .with(|s| items::create(s, None, "login", Some("mine".into()), fields))
        .unwrap();
    assert_eq!(next(&mut lines).await, Some(items_in(vault)));
    quiet(&mut lines).await;

    // Another member writes three items; they arrive in one sync batch.
    let other = DeviceSecret:[REDACTED]; 32]);
    agent
        .with(|s| {
            s.update(vault, |v, key| {
                Ok(v.add(
                    key,
                    other.device_id(),
                    other.join_consent(&vault, &key.device_id()),
                )?)
            })
        })
        .unwrap();
    assert_eq!(
        changes(&mut lines, 2).await,
        [Change::Vaults, devices_in(vault)]
    );
    let mut theirs = agent.with(|s| Ok(s.vault(&vault).clone())).unwrap();
    let batch: Vec<Vec<u8>> = (0..3)
        .map(|n| {
            let field = Field::new(FieldType::Secret, format!("theirs-{n}"));
            let (_, entry) = theirs
                .create_item(&other, "login", None, [("password".into(), field)])
                .unwrap();
            entry.encode()
        })
        .collect();
    agent.ready.send_replace(true);
    sync::Handler(agent.clone())
        .receive(*other.device_id().as_bytes(), batch)
        .await
        .unwrap();
    assert_eq!(
        agent.with(|s| Ok(s.vault(&vault).items().len())).unwrap(),
        4
    );
    assert_eq!(next(&mut lines).await, Some(items_in(vault)));
    quiet(&mut lines).await;

    // Stopping ends the stream with a final reply.
    agent.watchers.stopping();
    assert_eq!(next(&mut lines).await, Some(Change::Stopping));
    assert_eq!(next(&mut lines).await, None);
    assert_eq!(lines.next_line().await.unwrap(), None);
    connections.join_next().await.unwrap().unwrap().unwrap();
    assert_eq!(agent.watchers.len(), 0);
    agent.lock().await;
}

#[tokio::test]
async fn hanging_up_ends_a_watch_quietly() {
    let dir = tempfile::tempdir().unwrap();
    let agent = agent(dir.path());
    let mut connections = JoinSet::new();
    let (lines, write) = subscribe(&agent, &mut connections).await;
    assert_eq!(agent.watchers.len(), 1);
    drop((lines, write));
    tokio::time::timeout(STEP, connections.join_next())
        .await
        .unwrap()
        .unwrap()
        .unwrap()
        .unwrap();
    assert_eq!(agent.watchers.len(), 0);
}

#[tokio::test(start_paused = true)]
async fn a_watcher_that_stops_reading_cannot_stall_the_agent() {
    let dir = tempfile::tempdir().unwrap();
    let agent = agent(dir.path());
    let (server, mut client) = UnixStream::pair().unwrap();
    client.write_all(&request(Command::Watch)).await.unwrap();
    // Fill the agent's side of the socket: the client never reads.
    server.writable().await.unwrap();
    loop {
        match server.try_write(&[0; 8192]) {
            Ok(_) => {}
            Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => break,
            Err(error) => panic!("{error}"),
        }
    }
    let mut connections = JoinSet::new();
    connections.spawn(agent.clone().handle(server, MAX_LINE));
    while agent.watchers.len() == 0 {
        tokio::task::yield_now().await;
    }

    let start = tokio::time::Instant::now();
    for n in 0..10_000u32 {
        let mut id = [0; 32];
        id[..4].copy_from_slice(&n.to_le_bytes());
        agent.watchers.changed(&Changes {
            items: [VaultId::from_bytes(id)].into(),
            ..Changes::default()
        });
        agent.watchers.locked();
        agent.watchers.unlocked();
    }
    agent.lock().await;
    assert_eq!(start.elapsed(), Duration::ZERO, "publishing never waits");

    let result = tokio::time::timeout(watchers::SEND_TIMEOUT * 2, connections.join_next())
        .await
        .expect("the stuck watcher is dropped")
        .unwrap()
        .unwrap();
    assert!(result.is_err());
    assert!(start.elapsed() >= watchers::SEND_TIMEOUT);
    assert_eq!(agent.watchers.len(), 0);
    drop(client);
}

#[tokio::test]
async fn system_events_lock_unless_lock_on_sleep_is_off() {
    let dir = tempfile::tempdir().unwrap();
    let agent = agent(dir.path());
    let unlocked = || agent.session.lock().unwrap().is_some();
    let deliver = |events: &[SystemEvent]| {
        let (tx, rx) = mpsc::channel(events.len());
        for event in events {
            tx.try_send(*event).unwrap();
        }
        drop(tx);
        agent.clone().follow_system(rx)
    };
    let mut connections = JoinSet::new();
    let (mut lines, _write) = subscribe(&agent, &mut connections).await;

    agent.setup(passphrase(), "device".into()).await.unwrap();
    assert_eq!(next(&mut lines).await, Some(Change::Unlocked));
    deliver(&[SystemEvent::Sleep]).await;
    assert!(!unlocked());
    assert_eq!(next(&mut lines).await, Some(Change::Locked));

    for event in [SystemEvent::ScreenLocked, SystemEvent::Slept] {
        agent.unlock(passphrase(), None).await.unwrap();
        deliver(&[event]).await;
        assert!(!unlocked(), "{event:?} locks");
    }

    std::fs::write(&agent.paths.config, "lock_on_sleep = false\n").unwrap();
    agent.unlock(passphrase(), None).await.unwrap();
    deliver(&[
        SystemEvent::Sleep,
        SystemEvent::ScreenLocked,
        SystemEvent::Slept,
    ])
    .await;
    assert!(unlocked(), "turned off, nothing locks");

    // A config that doesn't parse locks: failing safe beats failing open.
    std::fs::write(&agent.paths.config, "lock_on_sleep = \"sometimes\"\n").unwrap();
    deliver(&[SystemEvent::Sleep]).await;
    assert!(!unlocked());
}

//! A real agent in a temporary home for the app's tests, and running the
//! headless runtime until something shows.

#![allow(dead_code, reason = "each test crate uses some of it")]

use std::collections::HashMap;
use std::ffi::OsString;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::time::{Duration, Instant};

use deadbolt_app::model::App;
use deadbolt_client::{Launch, Paths};
use rune::{Key, KeyEvent, Mods, Runtime};

pub const PASSPHRASE: &str = "correct horse";

/// `DEADBOLT_BIN`, else the `deadbolt` cargo already built next to this test
/// (`cargo test --workspace` builds it for the CLI's own tests), else one
/// built here into the test's own target dir, which doesn't wait on the outer
/// build's lock but compiles the CLI from scratch.
pub fn deadbolt() -> PathBuf {
    if let Some(bin) = std::env::var_os("DEADBOLT_BIN") {
        return bin.into();
    }
    let sibling = std::env::current_exe()
        .ok()
        .and_then(|exe| Some(exe.parent()?.parent()?.join("deadbolt")));
    if let Some(bin) = sibling.filter(|bin| bin.is_file()) {
        return bin;
    }
    let manifest = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../Cargo.toml");
    let target = Path::new(env!("CARGO_TARGET_TMPDIR")).join("cli");
    let out = Command::new(env!("CARGO"))
        .args([
            "build",
            "--quiet",
            "-p",
            "deadbolt-cli",
            "--message-format=json",
        ])
        .arg("--manifest-path")
        .arg(&manifest)
        .arg("--target-dir")
        .arg(&target)
        .stderr(Stdio::inherit())
        .output()
        .expect("running cargo");
    assert!(out.status.success(), "building deadbolt-cli failed");
    String::from_utf8(out.stdout)
        .unwrap()
        .lines()
        .filter(|l| l.contains("\"executable\"") && l.contains("\"name\":\"deadbolt\""))
        .find_map(|l| {
            let at = l.find("\"executable\":\"")? + "\"executable\":\"".len();
            Some(PathBuf::from(&l[at..at + l[at..].find('"')?]))
        })
        .expect("cargo reported no deadbolt executable")
}

pub struct Device {
    _dir: tempfile::TempDir,
    bin: PathBuf,
    vars: HashMap<&'static str, OsString>,
}

impl Device {
    pub fn new() -> Device {
        let dir = tempfile::Builder::new().prefix("db").tempdir().unwrap();
        let path = |name: &str| dir.path().join(name).into_os_string();
        let vars = HashMap::from([
            ("DEADBOLT_HOME", path("home")),
            ("XDG_RUNTIME_DIR", path("run")),
            ("XDG_STATE_HOME", path("state")),
            ("XDG_CONFIG_HOME", path("config")),
            ("DEADBOLT_NET", "local".into()),
            ("DEADBOLT_KDF", "fast".into()),
        ]);
        Device {
            _dir: dir,
            bin: deadbolt(),
            vars,
        }
    }

    /// Production Argon2 instead of the fast test setting: seconds in a debug
    /// build, long enough to act while it runs.
    pub fn with_slow_kdf(mut self) -> Device {
        self.vars.insert("DEADBOLT_KDF", "default".into());
        self
    }

    pub fn run(&self, args: &[&str]) {
        let status = Command::new(&self.bin)
            .args(args)
            .envs(&self.vars)
            .env("DEADBOLT_PASSPHRASE", PASSPHRASE)
            .env_remove("RUST_LOG")
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .status()
            .unwrap();
        assert!(status.success(), "deadbolt {args:?} failed");
    }

    pub fn output(&self, args: &[&str]) -> String {
        let out = Command::new(&self.bin)
            .args(args)
            .envs(&self.vars)
            .env("DEADBOLT_PASSPHRASE", PASSPHRASE)
            .env_remove("RUST_LOG")
            .stdin(Stdio::null())
            .output()
            .unwrap();
        assert!(out.status.success(), "deadbolt {args:?} failed");
        String::from_utf8(out.stdout).unwrap()
    }

    pub fn spawn(&self, args: &[&str]) -> std::process::Child {
        Command::new(&self.bin)
            .args(args)
            .envs(&self.vars)
            .env_remove("RUST_LOG")
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()
            .unwrap()
    }

    /// How the app starts this device's agent: a script that runs `deadbolt`
    /// with the device's environment, as the app's own would have.
    pub fn launch(&self) -> Launch {
        let script = self._dir.path().join("deadbolt");
        let mut body = String::from("#!/bin/sh\nexec env");
        for (name, value) in &self.vars {
            body.push_str(&format!(" {name}='{}'", value.to_string_lossy()));
        }
        body.push_str(&format!(" '{}' \"$@\"\n", self.bin.display()));
        std::fs::write(&script, body).unwrap();
        std::fs::set_permissions(&script, std::os::unix::fs::PermissionsExt::from_mode(0o755))
            .unwrap();
        Launch { program: script }
    }

    /// Writes `text` to a file named `name` in the device's temporary dir.
    pub fn file(&self, name: &str, text: &str) -> PathBuf {
        let path = self._dir.path().join(name);
        std::fs::write(&path, text).unwrap();
        path
    }

    pub fn paths(&self) -> Paths {
        Paths::from_vars(|name| {
            self.vars
                .get(name)
                .cloned()
                .or_else(|| std::env::var_os(name))
        })
    }
}

impl Drop for Device {
    fn drop(&mut self) {
        Command::new(&self.bin)
            .args(["agent", "stop"])
            .envs(&self.vars)
            .stdout(Stdio::null())
            .status()
            .ok();
    }
}

pub fn key(key: Key) -> KeyEvent {
    KeyEvent {
        key,
        mods: Mods::default(),
    }
}

/// Runs frames until `done` holds, the way a window would between wake-ups.
pub fn until(rt: &mut Runtime<App>, what: &str, done: impl Fn(&App) -> bool) {
    let start = Instant::now();
    while !done(&rt.state) {
        assert!(
            start.elapsed() < Duration::from_secs(20),
            "timed out waiting for {what}; screen {:?}",
            rt.state.screen
        );
        rt.frame(1.0 / 60.0);
        std::thread::sleep(Duration::from_millis(5));
    }
    rt.frame(1.0 / 60.0);
}

pub fn shows(rt: &Runtime<App>, s: &str) -> bool {
    rt.elements().iter().any(|e| e.text.as_deref() == Some(s))
}

