//! Sleep and screen-lock events, for `lock_on_sleep`. Two sources feed one
//! channel, neither with unsafe code:
//!
//! - Every platform: the wall clock running ahead of the monotonic clock,
//!   which stops while the computer sleeps. Seen on wake, so it backs up the
//!   sources below and is all Linux has for now.
//! - macOS: an `osascript` helper that observes NSWorkspace's will-sleep
//!   notification and the `com.apple.screenIsLocked` distributed notification
//!   on its own run loop. The agent's main thread runs Tokio, not a run loop,
//!   and objc2's observer APIs are all `unsafe`.

use std::time::Duration;

use tokio::sync::mpsc;
use tokio::task::JoinSet;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SystemEvent {
    /// The computer is about to sleep.
    #[cfg_attr(
        not(any(target_os = "macos", test)),
        expect(dead_code, reason = "only the macOS observer reports it")
    )]
    Sleep,
    /// The computer slept, seen on wake.
    Slept,
    #[cfg_attr(
        not(any(target_os = "macos", test)),
        expect(dead_code, reason = "only the macOS observer reports it")
    )]
    ScreenLocked,
}

/// How often the clocks are compared.
const CLOCK_TICK: Duration = Duration::from_secs(2);
/// Wall-clock time that passed beyond monotonic time to count as sleep, well
/// above clock corrections.
const SLEEP_GAP: Duration = Duration::from_secs(10);

/// Starts every source this platform has, sending into `events`. Dropping
/// the set stops them.
pub fn spawn(events: mpsc::Sender<SystemEvent>) -> JoinSet<()> {
    let mut sources = JoinSet::new();
    #[cfg(target_os = "macos")]
    sources.spawn(macos::run(events.clone()));
    sources.spawn(clock(events));
    sources
}

/// Whether the computer slept between two clock readings.
fn slept(wall: Duration, monotonic: Duration) -> bool {
    wall > monotonic + SLEEP_GAP
}

async fn clock(events: mpsc::Sender<SystemEvent>) {
    let mut tick = tokio::time::interval(CLOCK_TICK);
    let mut last = (crate::config::wall_clock(), std::time::Instant::now());
    loop {
        tick.tick().await;
        let now = (crate::config::wall_clock(), std::time::Instant::now());
        let wall = now.0.saturating_sub(last.0);
        let monotonic = now.1.saturating_duration_since(last.1);
        last = now;
        if slept(wall, monotonic) && events.send(SystemEvent::Slept).await.is_err() {
            return;
        }
    }
}

#[cfg(target_os = "macos")]
mod macos {
    use std::process::Stdio;
    use std::time::Duration;

    use anyhow::{Context, Result, bail};
    use tokio::io::{AsyncBufReadExt, BufReader};
    use tokio::sync::mpsc;
    use tracing::{info, warn};

    use super::SystemEvent;

    const SCREEN_LOCKED: &str = "com.apple.screenIsLocked";
    const RETRY: Duration = Duration::from_secs(5);
    const RETRY_MAX: Duration = Duration::from_secs(300);
    /// Prints `sleep` or `lock` per notification, and exits once its parent
    /// (the agent) is gone.
    const HELPER: &str = r#"
ObjC.import('AppKit');
ObjC.import('stdlib');
ObjC.import('unistd');
function run(argv) {
  var out = $.NSFileHandle.fileHandleWithStandardOutput;
  var parent = $.getppid();
  function say(line) {
    out.writeData($(line + '\n').dataUsingEncoding($.NSUTF8StringEncoding));
  }
  ObjC.registerSubclass({
    name: 'DeadboltObserver',
    methods: {
      'sleep:': { types: ['void', ['id']], implementation: function () { say('sleep'); } },
      'lock:': { types: ['void', ['id']], implementation: function () { say('lock'); } },
      'tick:': {
        types: ['void', ['id']],
        implementation: function () { if ($.getppid() != parent) { $.exit(0); } },
      },
    },
  });
  var observer = $.DeadboltObserver.alloc.init;
  $.NSWorkspace.sharedWorkspace.notificationCenter.addObserverSelectorNameObject(
    observer, 'sleep:', $.NSWorkspaceWillSleepNotification, $());
  $.NSDistributedNotificationCenter.defaultCenter.addObserverSelectorNameObject(
    observer, 'lock:', argv[0], $());
  $.NSTimer.scheduledTimerWithTimeIntervalTargetSelectorUserInfoRepeats(5, observer, 'tick:', $(), true);
  say('ready');
  $.NSRunLoop.currentRunLoop.run;
}
"#;

    pub async fn run(events: mpsc::Sender<SystemEvent>) {
        let mut retry = RETRY;
        loop {
            match helper(&events, &mut retry).await {
                Ok(()) => return,
                Err(error) => warn!("sleep and screen-lock watcher stopped: {error:#}"),
            }
            tokio::time::sleep(retry).await;
            retry = (retry * 2).min(RETRY_MAX);
        }
    }

    /// Runs the helper until it exits (an error) or `events` closes.
    async fn helper(events: &mpsc::Sender<SystemEvent>, retry: &mut Duration) -> Result<()> {
        let mut child = tokio::process::Command::new("/usr/bin/osascript")
            .args(["-l", "JavaScript", "-e", HELPER, SCREEN_LOCKED])
            .stdin(Stdio::null())
            .stdout(Stdio::piped())
            .kill_on_drop(true)
            .spawn()
            .context("starting osascript")?;
        let stdout = child.stdout.take().context("no helper output")?;
        let mut lines = BufReader::new(stdout).lines();
        while let Some(line) = lines.next_line().await? {
            let event = match line.as_str() {
                "ready" => {
                    info!("watching for sleep and screen lock");
                    *retry = RETRY;
                    continue;
                }
                "sleep" => SystemEvent::Sleep,
                "lock" => SystemEvent::ScreenLocked,
                _ => continue,
            };
            if events.send(event).await.is_err() {
                return Ok(());
            }
        }
        bail!("osascript exited ({})", child.wait().await?)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn only_a_clear_jump_of_the_wall_clock_counts_as_sleep() {
        let s = Duration::from_secs;
        assert!(!slept(s(2), s(2)));
        assert!(!slept(s(11), s(2)), "a clock correction is not sleep");
        assert!(slept(s(600), s(2)));
        assert!(
            !slept(s(0), s(2)),
            "the wall clock moving back is not sleep"
        );
    }
}

//! `watch` subscriptions. Publishing marks what changed in each watcher's
//! pending set and wakes it; it never waits on a watcher. Each watcher's
//! connection drains its set after a short window, so bursts coalesce, and a
//! set that grows past [`MAX_PENDING`] collapses to one `resync`.

use std::collections::BTreeSet;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::time::Duration;

use deadbolt_core::VaultId;
use tokio::sync::Notify;

use super::session::Changes;
use crate::protocol::Change;

/// How long a woken watcher gathers changes before sending them.
pub const COALESCE: Duration = Duration::from_millis(25);
/// How long one change may take to reach a watcher before it is dropped.
pub const SEND_TIMEOUT: Duration = Duration::from_secs(5);
/// Most vaults a watcher holds as pending before it gets `resync` instead.
const MAX_PENDING: usize = 64;

#[derive(Default)]
pub struct Watchers {
    list: Mutex<Vec<Arc<Watcher>>>,
    /// Set under `list`'s lock, so a late subscriber still hears `stopping`.
    stopped: AtomicBool,
}

#[derive(Default)]
struct Watcher {
    pending: Mutex<Pending>,
    wake: Notify,
}

/// What a watcher hasn't been told yet.
#[derive(Debug, Default)]
struct Pending {
    /// The store locked since the last drain.
    locked: bool,
    /// The store unlocked after the last lock.
    unlocked: bool,
    vaults: bool,
    items: BTreeSet<VaultId>,
    devices: BTreeSet<VaultId>,
    resync: bool,
    stopping: bool,
}

impl Pending {
    fn is_empty(&self) -> bool {
        !(self.locked || self.unlocked || self.vaults || self.resync || self.stopping)
            && self.items.is_empty()
            && self.devices.is_empty()
    }

    fn changed(&mut self, changes: &Changes) {
        self.vaults |= changes.vaults;
        self.items.extend(&changes.items);
        self.devices.extend(&changes.devices);
        if self.items.len() + self.devices.len() > MAX_PENDING {
            self.resync = true;
            self.vaults = false;
            self.items.clear();
            self.devices.clear();
        }
    }

    /// Everything pending, in order, leaving it empty.
    fn take(&mut self) -> Vec<Change> {
        let pending = std::mem::take(self);
        let mut out = Vec::new();
        if pending.resync {
            out.push(Change::Resync);
        } else {
            if pending.locked {
                out.push(Change::Locked);
            }
            if pending.unlocked {
                out.push(Change::Unlocked);
            }
            if pending.vaults {
                out.push(Change::Vaults);
            }
            out.extend(pending.devices.iter().map(|v| Change::Devices {
                vault: v.to_string(),
            }));
            out.extend(pending.items.iter().map(|v| Change::Items {
                vault: v.to_string(),
            }));
        }
        if pending.stopping {
            out.push(Change::Stopping);
        }
        out
    }
}

impl Watchers {
    pub fn subscribe(&self) -> Subscription<'_> {
        let watcher = Arc::new(Watcher::default());
        let mut list = self.list.lock().unwrap_or_else(|e| e.into_inner());
        if self.stopped.load(Ordering::SeqCst) {
            watcher
                .pending
                .lock()
                .unwrap_or_else(|e| e.into_inner())
                .stopping = true;
            watcher.wake.notify_one();
        }
        list.push(watcher.clone());
        drop(list);
        Subscription {
            watchers: self,
            watcher,
        }
    }

    #[cfg(test)]
    pub fn len(&self) -> usize {
        self.list.lock().unwrap_or_else(|e| e.into_inner()).len()
    }

    fn publish(&self, mark: impl Fn(&mut Pending)) {
        mark_all(&self.list.lock().unwrap_or_else(|e| e.into_inner()), mark);
    }

    pub fn changed(&self, changes: &Changes) {
        if !changes.is_empty() {
            self.publish(|p| p.changed(changes));
        }
    }

    pub fn locked(&self) {
        self.publish(|p| {
            // What changed before the lock is moot; clients refetch on unlock.
            *p = Pending {
                locked: true,
                resync: p.resync,
                stopping: p.stopping,
                ..Pending::default()
            };
        });
    }

    pub fn unlocked(&self) {
        self.publish(|p| p.unlocked = true);
    }

    pub fn stopping(&self) {
        let list = self.list.lock().unwrap_or_else(|e| e.into_inner());
        self.stopped.store(true, Ordering::SeqCst);
        mark_all(&list, |p| p.stopping = true);
    }
}

fn mark_all(list: &[Arc<Watcher>], mark: impl Fn(&mut Pending)) {
    for watcher in list {
        mark(&mut watcher.pending.lock().unwrap_or_else(|e| e.into_inner()));
        watcher.wake.notify_one();
    }
}

/// One watcher, removed when dropped.
pub struct Subscription<'a> {
    watchers: &'a Watchers,
    watcher: Arc<Watcher>,
}

impl Subscription<'_> {
    /// Waits for changes, gathers them for [`COALESCE`] and returns them.
    /// Cancel-safe: the pending set, not the wake-up, says whether to send,
    /// and it is only taken at the end.
    pub async fn next(&self) -> Vec<Change> {
        loop {
            let idle = self.pending().is_empty();
            if idle {
                self.watcher.wake.notified().await;
                continue;
            }
            tokio::time::sleep(COALESCE).await;
            let changes = self.pending().take();
            if !changes.is_empty() {
                return changes;
            }
        }
    }

    fn pending(&self) -> std::sync::MutexGuard<'_, Pending> {
        self.watcher
            .pending
            .lock()
            .unwrap_or_else(|e| e.into_inner())
    }
}

impl Drop for Subscription<'_> {
    fn drop(&mut self) {
        self.watchers
            .list
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .retain(|w| !Arc::ptr_eq(w, &self.watcher));
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn vault(n: u8) -> VaultId {
        VaultId::from_bytes([n; 32])
    }

    fn items(vaults: impl IntoIterator<Item = u8>) -> Changes {
        Changes {
            items: vaults.into_iter().map(vault).collect(),
            ..Changes::default()
        }
    }

    #[test]
    fn bursts_coalesce_per_vault_and_a_lock_drops_what_came_before() {
        let watchers = Watchers::default();
        let sub = watchers.subscribe();
        let take = || sub.watcher.pending.lock().unwrap().take();
        for _ in 0..100 {
            watchers.changed(&items([1, 2]));
        }
        assert_eq!(
            take(),
            [
                Change::Items {
                    vault: vault(1).to_string()
                },
                Change::Items {
                    vault: vault(2).to_string()
                }
            ]
        );
        watchers.changed(&items([1]));
        watchers.locked();
        assert_eq!(take(), [Change::Locked]);
        watchers.locked();
        watchers.unlocked();
        watchers.changed(&items([3]));
        assert_eq!(
            take(),
            [
                Change::Locked,
                Change::Unlocked,
                Change::Items {
                    vault: vault(3).to_string()
                }
            ]
        );
        watchers.unlocked();
        watchers.locked();
        assert_eq!(take(), [Change::Locked]);
        watchers.stopping();
        assert_eq!(take(), [Change::Stopping]);
        assert!(take().is_empty());
        let late = watchers.subscribe();
        assert_eq!(
            late.watcher.pending.lock().unwrap().take(),
            [Change::Stopping]
        );
    }

    #[tokio::test(start_paused = true)]
    async fn cancelling_next_keeps_the_wake_up() {
        let watchers = Watchers::default();
        let sub = watchers.subscribe();
        watchers.changed(&items([1]));
        // Cancelled mid-coalesce, after it took the wake-up.
        let cancelled = tokio::time::timeout(COALESCE / 2, sub.next()).await;
        assert!(cancelled.is_err());
        let changes = tokio::time::timeout(COALESCE * 2, sub.next()).await;
        assert_eq!(
            changes.ok(),
            Some(vec![Change::Items {
                vault: vault(1).to_string()
            }])
        );
        // Nothing pending: it waits.
        assert!(
            tokio::time::timeout(COALESCE * 4, sub.next())
                .await
                .is_err()
        );
    }

    #[test]
    fn a_watcher_that_falls_behind_gets_one_resync_and_unsubscribes_on_drop() {
        let watchers = Watchers::default();
        let sub = watchers.subscribe();
        for n in 0..=MAX_PENDING as u8 {
            watchers.changed(&items([n]));
        }
        watchers.changed(&items([1]));
        watchers.locked();
        watchers.stopping();
        let changes = sub.watcher.pending.lock().unwrap().take();
        assert_eq!(changes, [Change::Resync, Change::Stopping]);
        assert_eq!(watchers.len(), 1);
        drop(sub);
        assert_eq!(watchers.len(), 0);
    }
}
